INSERT INTO `products` (`id`, `name`, `description`, `price`, `image`, `available`, `created_at`, `category`, `detailed_description`, `dimensions`, `price_info`, `features`, `additional_images`) VALUES
(1, 'Jungle Book', 'Stap rechtstreeks in het tijdloze verhaal van Jungle Book met ons adembenemende Jungle Book Springkasteel! Breng de jungle naar je eigen achtertuin en laat de kinderen deelnemen aan een onvergetelijk avontuur met Lowietje en zijn vrienden.', 115.00, 'Vooraanzicht Jungle Book.jpg', 1, '2024-11-13 14:43:00', 'Dieren', 'Betreed de betoverende wereld van de Jungle en zie de verwondering in de ogen van de kinderen terwijl ze spelen in ons Jungle Book Springkasteel. Reserveer nu en laat het jungle avontuur beginnen!', '4m x 4m', '1 dag: €115\n2 dagen: €200\nVanaf 3 dagen krijgt u 20% korting', 'Jungle Avontuur: Creëer je eigen jungleverhaal met ons prachtige springkasteel, versiert met kleurrijke beelden en aapjes uit de Jungle.\r\nInteractieve Speelelementen: Laat kinderen zich wanen in het hart van de jungle met leuke tekeningen, een groot springoppervlak en de avontuurlijke glijbaan.\r\nVeilig en Magisch: Gebouwd met veiligheid als prioriteit, biedt ons Jungle Book Springkasteel een betoverende speelervaring voor alle kleine ontdekkingsreizigers.', 'Zijaanzicht Jungle Book.jpg'),
(2, '\'t Voetballerke', 'Ben jij klaar voor een dag vol plezier, actie en voetbalpret? Laat kinderen (en volwassenen!) zich uitleven op ons voetbalthema springkasteel! Met een dynamisch ontwerp vol voetbalsymbolen, doelwitten en speelse obstakels voelt iedereen zich een kampioen op dit kasteel.', 120.00, 'Vooraanzicht voetbal.jpg', 1, '2024-11-13 14:43:00', 'Sport', 'Perfect voor:\r\n\r\nVerjaardagsfeestjes\r\nSportdagen & toernooien\r\nBedrijfsfeesten\r\nFamiliedagen', '5m40 x 5m x 3m61', '1 dag: € 120\n2 dagen: € 210\nVanaf 3 dagen krijgt u 20% korting', 'Veilig & stevig: Voldoet aan de hoogste veiligheidseisen\r\nOrigineel thema: Brengt de sfeer van het stadion naar jouw feest\r\nWeerbestendig: Dus regen of zonneschijn, het plezier gaat door!\r\nReserveer snel en maak je feestje legendarisch!', 'Zijaanzicht voetbal.jpg,Binnenkant voetbal.jpg'),
(3, 'Aloha Hawaii', 'Breng de zomerse vibes naar jouw feest met ons adembenemende Aloha Hawaii Springkasteel! Creëer een exotische oase in je eigen achtertuin en laat de kinderen genieten van de magie van Hawaii.', 120.00, 'Vooraanzicht aloha.jpg', 1, '2024-11-13 14:43:00', 'Tropisch', 'Transformeer je achtertuin in een tropisch paradijs en zie de glimlach op de gezichten van de kinderen terwijl ze zich vermaken in het Aloha Hawaii Springkasteel. Reserveer nu en laat het tropische avontuur beginnen!', '5m40 x 5m x 3m60', '1 dag: € 120\n2 dagen: € 210\nVanaf 3 dagen krijgt u 20% korting', 'Eilandavontuur: Neem een duik in de Hawaiiaanse sfeer met ons prachtige springkasteel, omringd door zonnige stranden en kleurrijke bloemen.\r\nTropische Glijbaan: Voeg een dosis spanning toe en ga van de opblaasbare glijbaan, en geniet van een tropische afdaling. Glijplezier verzekerd.\r\nVeilig en Zorgeloos Plezier: Gemaakt met hoogwaardig materiaal, biedt ons Aloha Hawaii Springkasteel een veilige en duurzame speelervaring.', 'Zijaanzicht aloha.jpg'),
(4, 'Stormbaan', 'Daag de avonturiers uit met ons opwindende Stormbaan Springkasteel! Transformeer je evenement in een spectaculaire race vol obstakels, spanning en pure opwinding. Durf jij de uitdaging aan?', 140.00, 'Zijaanzicht 1 stormbaan.jpg', 1, '2024-11-13 14:43:00', 'Obstakel Parcours', 'Laat de adrenaline stromen en de competitieve geesten ontwaken met ons Stormbaan Springkasteel. Reserveer nu en geef deelnemers de ultieme uitdaging waar ze nog lang over zullen napraten!', '9m x 4m', '1 dag: € 140\n2 dagen: € 250\nVanaf 3 dagen krijgt u 20% korting', 'Ultieme Stormbaan: Laat kinderen hun grenzen verleggen met onze gigantische stormbaan, ontworpen voor maximale fun en actie.\r\nDiversiteit aan Obstakels: Overwin tunnels, hindernissen en meer! Een ongekende variëteit aan obstakels wacht op de dappere deelnemers.\r\nVeiligheid Voorop: Onze Stormbaan is gebouwd met hoogwaardige materialen, zodat kinderen veilig kunnen genieten van het ultieme avontuur.', 'Zijaanzicht 2 stormbaan.jpg');
